using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class ConfigureOrganicForest {
 const string Folder="Assets/Game/Generated/RealisticForest/";
 static Texture2D Texture(string path,bool normal=false){var imp=AssetImporter.GetAtPath(path) as TextureImporter;if(imp==null)throw new Exception("Missing texture "+path);if(path.ToLowerInvariant().Contains("rough")&&imp.sRGBTexture){imp.sRGBTexture=false;imp.SaveAndReimport();}if(normal&&imp.textureType!=TextureImporterType.NormalMap){imp.textureType=TextureImporterType.NormalMap;imp.SaveAndReimport();}return AssetDatabase.LoadAssetAtPath<Texture2D>(path);}
 static Material Ground(string name,float mud){var existing=AssetDatabase.LoadAssetAtPath<Material>(Folder+name+".mat");if(existing!=null)return existing;var material=new Material(Shader.Find("Game/Realistic Forest Ground")){name=name};string[] slots={"Needle","Moss","Grass","Mud"},sets={"forrest_ground_03","forest_leaves_02","leafy_grass","mud_forest"};for(int i=0;i<slots.Length;i++){string prefix="Assets/Game/Art/RealisticForest/"+sets[i]+"/"+sets[i];material.SetTexture("_"+slots[i]+"Map",Texture(prefix+"-Diffuse.jpg"));material.SetTexture("_"+slots[i]+"Normal",Texture(prefix+"-nor_gl.jpg",true));material.SetTexture("_"+slots[i]+"Rough",Texture(prefix+"-Rough.jpg"));}string dirt="Assets/Game/Art/ForestEnhancement/gravel_floor_04/gravel_floor_04_";material.SetTexture("_DirtMap",Texture(dirt+"diff_2k.jpg"));material.SetTexture("_DirtNormal",Texture(dirt+"nor_gl_2k.jpg",true));material.SetTexture("_DirtRough",Texture(dirt+"rough_2k.jpg"));material.SetFloat("_MudDominance",mud);AssetDatabase.CreateAsset(material,Folder+name+".mat");return material;}
 static Mesh[] Clumps(Renderer renderer,string name,float cell,float minHeight,float maxHeight){
 var filter=renderer.GetComponent<MeshFilter>();var original=filter.sharedMesh;var source=original.vertices;var uv=original.uv;var indices=original.triangles;var bins=new Dictionary<Vector2Int,List<int>>();
 for(int i=0;i<indices.Length;i+=3){var c=renderer.transform.TransformPoint((source[indices[i]]+source[indices[i+1]]+source[indices[i+2]])/3);var key=new Vector2Int(Mathf.FloorToInt(c.x/cell),Mathf.FloorToInt(c.z/cell));if(!bins.TryGetValue(key,out var list))bins[key]=list=new List<int>();list.AddRange(new[]{indices[i],indices[i+1],indices[i+2]});}
 var meshes=new List<Mesh>();foreach(var pair in bins.OrderByDescending(p=>p.Value.Count)){
 var used=pair.Value.Distinct().ToArray();if(used.Length<4||used.Length>2000)continue;var points=used.Select(i=>renderer.transform.TransformPoint(source[i])).ToArray();var bounds=new Bounds(points[0],Vector3.zero);foreach(var p in points)bounds.Encapsulate(p);if(bounds.size.y<minHeight||bounds.size.y>maxHeight||bounds.size.x>cell*1.8f||bounds.size.z>cell*1.8f)continue;
 var origin=new Vector3(bounds.center.x,bounds.min.y,bounds.center.z);var lookup=new Dictionary<int,int>();for(int i=0;i<used.Length;i++)lookup[used[i]]=i;var mesh=new Mesh{name=name+" "+meshes.Count};mesh.vertices=points.Select(p=>(p-origin)*(name=="Green understory"?1/Mathf.Max(.2f,bounds.size.y):1)).ToArray();mesh.uv=used.Select(i=>uv[i]).ToArray();mesh.triangles=pair.Value.Select(i=>lookup[i]).ToArray();mesh.normals=used.Select(i=>renderer.transform.TransformDirection(original.normals[i])).ToArray();mesh.RecalculateTangents();mesh.RecalculateBounds();var oldMesh=AssetDatabase.LoadAssetAtPath<Mesh>(Folder+mesh.name+".asset");if(oldMesh==null)AssetDatabase.CreateAsset(mesh,Folder+mesh.name+".asset");else{UnityEngine.Object.DestroyImmediate(mesh);mesh=oldMesh;}meshes.Add(mesh);if(meshes.Count==12)break;}
 if(meshes.Count==0)throw new Exception("No usable "+name);return meshes.ToArray();
 }
 static Material Foliage(string name,string texture){var material=new Material(Shader.Find("Game/Living Forest")){name=name,enableInstancing=true};material.SetTexture("_BaseMap",Texture(texture));material.SetFloat("_AlphaClip",1);material.SetFloat("_Cutoff",.38f);material.SetFloat("_Cull",0);material.SetFloat("_SnowAmount",0);material.SetFloat("_FoliageLight",.48f);material.SetColor("_BaseColor",new Color(1.08f,1.15f,.98f,1));material.SetFloat("_LeafFlutter",.035f);material.SetFloat("_LocalWindAnchor",1);material.renderQueue=2450;AssetDatabase.CreateAsset(material,Folder+name+".mat");return material;}
 public static object Main(){
 if(Application.isPlaying)throw new Exception("Expected Edit Mode");var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(scene.isDirty)throw new Exception("Save current scene before changing palette");const string backup="Assets/Game/Scenes/BeforeOrganicForest.unity";if(!File.Exists(backup))EditorSceneManager.SaveScene(scene,backup,true);
 Directory.CreateDirectory(Folder);AssetDatabase.Refresh();var palette=AssetDatabase.LoadAssetAtPath<ExplorationPalette>("Assets/Game/Generated/ExplorationWorld/World palette.asset");if(palette.grassClumps!=null&&palette.grassClumps.Length>0&&palette.forest.shader.name=="Game/Realistic Forest Ground")throw new Exception("Organic palette already configured");palette.forest=Ground("Organic forest floor",0);palette.road=Ground("Worn forest twin track",0);palette.mud=Ground("Waterlogged road",.92f);palette.bog=Ground("Forest bog soil",.7f);
 var model=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Game/Art/Forest/Dirt road scene.fbx"));try{var renderers=model.GetComponentsInChildren<Renderer>();palette.shrubClumps=Clumps(renderers.First(r=>r.sharedMaterials.Any(m=>m.name=="Forest_Bush")),"Forest shrub",3.5f,.35f,3.2f);palette.grassClumps=Clumps(renderers.First(r=>r.sharedMaterials.Any(m=>m.name=="Grass_Vegetation_Green")),"Green understory",3.5f,.1f,4f);}finally{UnityEngine.Object.DestroyImmediate(model);}
 palette.grassDetail=Foliage("Green grasses","Assets/Game/Generated/Forest_Grass_Vegetation_Green_Alpha.png");palette.shrubDetail=Foliage("Forest shrubs","Assets/Game/Generated/Forest_Forest_Bush_Alpha.png");
 var old=UnityEngine.Object.FindAnyObjectByType<ForestDayNightWeather>().profile;palette.weather=UnityEngine.Object.Instantiate(old);palette.weather.name="Natural forest daylight";palette.weather.startHour=11;palette.weather.daylightIntensity=1.85f;palette.weather.initialCloudCover=.3f;palette.weather.daylightAmbient=new Color(.61f,.69f,.64f);AssetDatabase.CreateAsset(palette.weather,Folder+"Natural forest daylight.asset");
 var seen=new HashSet<Material>();foreach(var prefab in palette.trees)foreach(var renderer in prefab.GetComponentsInChildren<Renderer>())if(seen.Add(renderer.sharedMaterial)){var m=renderer.sharedMaterial;m.SetFloat("_FoliageLight",m.name.Contains("Trunk")?0:.32f);m.SetColor("_BaseColor",Color.white);EditorUtility.SetDirty(m);}
 EditorUtility.SetDirty(palette);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(scene);return new{success=true,grassMeshes=palette.grassClumps.Length,shrubMeshes=palette.shrubClumps.Length,pbrSets=4};
 }
}




